// A simple matrix type alias matching the requested `Matrix<i8>` idea.
type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(shape.len() == 2, "shape must have length 2");
    let r: usize = shape[0] as usize;
    let c: usize = shape[1] as usize;

    assert!(r > 0 && c > 0, "R and C must be positive");
    assert!(!a.is_empty(), "input array must have positive length");

    let n = a.len();

    // Compatibility check per problem statement.
    assert!(
        n == r || n == c,
        "input length must equal R or C for broadcasting"
    );

    // If both match, rule says: if R equals length, treat as column vector.
    if n == r {
        // Column vector: each row i is filled with a[i], replicated across columns.
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for i in 0..r {
            ret.push(vec![a[i]; c]);
        }
        ret
    } else {
        // Row vector: each row is the entire array a, replicated across rows.
        // Here n == c must hold.
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            ret.push(a.clone());
        }
        ret
    }
}